{
  "definition_simple": "指可以随身携带的电子设备，如手机、平板电脑等。",
  "definition_standard": "指能够随身携带、具有计算和通信功能的电子设备，通常包括智能手机、平板电脑、笔记本电脑等。",
  "pos": "名词",
  "semantic_class": "concrete",
  "sentences": [
    {
      "sentence": "这个行动装置很小。",
      "tier": "T1"
    },
    {
      "sentence": "我用行动装置听音乐。",
      "tier": "T2"
    },
    {
      "sentence": "她每天带着行动装置出门。",
      "tier": "T2"
    },
    {
      "sentence": "行动装置的功能越来越强大。",
      "tier": "T3"
    },
    {
      "sentence": "很多人离不开行动装置。",
      "tier": "T3"
    },
    {
      "sentence": "合理使用行动装置有助于提高工作效率。",
      "tier": "T4"
    },
    {
      "sentence": "学校禁止学生在课堂上使用行动装置。",
      "tier": "T4"
    },
    {
      "sentence": "医疗行业引入了专用行动装置来监测患者状况。",
      "tier": "T5"
    },
    {
      "sentence": "企业必须重视行动装置的安全管理。",
      "tier": "T5"
    },
    {
      "sentence": "在人工智能技术的推动下，行动装置正演变为个人数字助理。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "行动装饰",
      "explanation": "“装饰”(zhuāng shì)与“装置”(zhuāng zhì)声母sh与zh不同，但韵母相同，在快速口语中易听混。"
    },
    {
      "word": "行动装帧",
      "explanation": "“装帧”(zhuāng zhēn)与“装置”(zhuāng zhì)韵母en与i差异，但前两字相同，整体音近，容易混淆。"
    },
    {
      "word": "行动装配",
      "explanation": "“装配”(zhuāng pèi)与“装置”仅最后一字不同，声母p与zh，口语中因连续发音可能产生误听。"
    }
  ],
  "primary_collocate": "使用",
  "collocation_distractors": [
    {
      "word": "购买",
      "reason": "“购买”是交易行为，虽可与行动装置搭配，但不是最固定自然的搭配，更常见的是“使用”。"
    },
    {
      "word": "维修",
      "reason": "“维修”是售后行为，与行动装置搭配频率较低，且不构成习惯性固定搭配。"
    },
    {
      "word": "设计",
      "reason": "“设计”是创造过程，行动装置是结果，二者语义有关联但并非典型搭配。"
    }
  ],
  "collocation_wrong_collocate": {
    "word": "穿戴",
    "reason": "“穿戴”通常用于衣物或饰品，行动装置一般说“携带”而非“穿戴”，虽有个别可穿戴设备，但此搭配不通用。"
  },
  "cloze_distractors": [
    {
      "word": "行动电话",
      "reason": "“行动电话”特指手机，范围比行动装置窄，不能替换所有行动装置。"
    },
    {
      "word": "电脑",
      "reason": "“电脑”通常指台式或笔记本电脑，与行动装置概念交叉但不完全等同，一些行动装置（如智能手表）不被称为电脑。"
    },
    {
      "word": "耳机",
      "reason": "“耳机”是配件，不是设备本身，填入后句子语义不合逻辑。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "行动装置吃了饭。",
      "reason": "主语错误：行动装置是无生命物体，不能执行“吃”的动作。"
    },
    {
      "sentence": "我行动装置是红色的。",
      "reason": "成分缺失：缺少领属助词“的”或限定词，正确应为“我的行动装置是红色的”或“这个行动装置是红色的”。"
    },
    {
      "sentence": "他行动装置下载了游戏。",
      "reason": "介词缺失：缺少“用”或“在”，正确应为“他用行动装置下载了游戏”或“他在行动装置上下载了游戏”。"
    }
  ],
  "spot_incorrect": {
    "sentence": "他每天用行动装置玩耍析。",
    "error_description": "“析”为多余字，正确应为“玩耍”。",
    "corrected_sentence": "他每天用行动装置玩耍。"
  },
  "word_family_forms": [],
  "word_family_fake_forms": [
    {
      "form": "行动装置化",
      "reason": "“行动装置化”不是标准词汇，中文中无此派生形式，可能被误认为表示“变成行动装置”的过程。"
    },
    {
      "form": "行动装置性",
      "reason": "“行动装置性”不是规范词语，易被误认为表示“行动装置的性质”，但中文通常用“行动装置的属性”等表达。"
    },
    {
      "form": "行动装置者",
      "reason": "“行动装置者”是生造词，意为“使用行动装置的人”，但中文更常用“用户”或“使用者”。"
    }
  ],
  "syn_ant_candidates": [
    {
      "word": "移动设备",
      "type": "synonym",
      "reason": "与行动装置意义相同，为常见同义替换。"
    },
    {
      "word": "手持装置",
      "type": "synonym",
      "reason": "强调可手持的特性，与行动装置概念重叠。"
    },
    {
      "word": "便携终端",
      "type": "synonym",
      "reason": "指便于携带的终端设备，与行动装置同义。"
    },
    {
      "word": "台式电脑",
      "type": "antonym",
      "reason": "台式电脑是固定设备，与行动装置的便携性相反。"
    }
  ],
  "particle_candidates": []
}
